//! `assets/walker.glb`, the slice's one character, is generated by this file and committed (as the
//! pond's GLBs are): a 15-joint humanoid of boxes, each box skinned whole to its joint, with an
//! `Idle` and a `Walk` whose hips travel 1.6 m a 0.8 s cycle (the root motion). The row checks the
//! committed bytes still equal the generator's and that `gfx.character` takes them.
//! Regenerate with `GENEX_UPDATE_ASSETS=1 rust-env.sh cargo test -p slice --test walker_glb`.

use std::path::PathBuf;

use genex::math::{Mat4, Quat, Vec3, vec3};
use genex::prelude::*;
use genex::{AssetTable, Runtime};

const GLB_MAGIC: u32 = 0x4654_6c67;
const CHUNK_JSON: u32 = 0x4e4f_534a;
const CHUNK_BIN: u32 = 0x004e_4942;
const FLOAT: u32 = 5126;
const UNSIGNED_SHORT: u32 = 5123;
/// The walk's cycle, seconds, and how far the hips travel in it, metres.
const WALK_CYCLE: f32 = 0.8;
const WALK_TRAVEL: f32 = 1.6;
/// The idle's cycle, seconds.
const IDLE_CYCLE: f32 = 2.0;
/// The hips' rest height, metres.
const HIPS_HEIGHT: f32 = 0.95;

/// A joint: name, parent, rest translation from the parent.
struct Joint {
    name: &'static str,
    parent: Option<usize>,
    at: Vec3,
}

/// A box skinned to `joint`: its centre in the joint's rest frame, half extents and material.
struct Part {
    joint: usize,
    center: Vec3,
    half: Vec3,
    material: usize,
}

const SKIN: usize = 0;
const SHIRT: usize = 1;
const TROUSERS: usize = 2;
const BOOTS: usize = 3;
const MATERIALS: [(&str, [f32; 4]); 4] =
    [("skin", [0.86, 0.66, 0.52, 1.0]), ("shirt", [0.18, 0.42, 0.66, 1.0]), ("trousers", [0.24, 0.22, 0.2, 1.0]), ("boots", [0.36, 0.22, 0.12, 1.0])];

fn joints() -> Vec<Joint> {
    let j = |name, parent, at| Joint { name, parent, at };
    vec![
        j("Hips", None, vec3(0.0, HIPS_HEIGHT, 0.0)),
        j("Spine", Some(0), vec3(0.0, 0.12, 0.0)),
        j("Chest", Some(1), vec3(0.0, 0.25, 0.0)),
        j("Head", Some(2), vec3(0.0, 0.3, 0.0)),
        j("LeftUpperArm", Some(2), vec3(0.22, 0.22, 0.0)),
        j("LeftLowerArm", Some(4), vec3(0.0, -0.28, 0.0)),
        j("RightUpperArm", Some(2), vec3(-0.22, 0.22, 0.0)),
        j("RightLowerArm", Some(6), vec3(0.0, -0.28, 0.0)),
        j("LeftUpperLeg", Some(0), vec3(0.1, -0.05, 0.0)),
        j("LeftLowerLeg", Some(8), vec3(0.0, -0.41, 0.0)),
        j("LeftFoot", Some(9), vec3(0.0, -0.41, 0.0)),
        j("RightUpperLeg", Some(0), vec3(-0.1, -0.05, 0.0)),
        j("RightLowerLeg", Some(11), vec3(0.0, -0.41, 0.0)),
        j("RightFoot", Some(12), vec3(0.0, -0.41, 0.0)),
        j("Neck", Some(2), vec3(0.0, 0.26, 0.0)),
    ]
}

fn parts() -> Vec<Part> {
    let p = |joint, center, half, material| Part { joint, center, half, material };
    let arm = vec3(0.05, 0.14, 0.05);
    let leg = vec3(0.07, 0.205, 0.07);
    vec![
        p(0, vec3(0.0, 0.0, 0.0), vec3(0.16, 0.09, 0.1), TROUSERS),
        p(1, vec3(0.0, 0.1, 0.0), vec3(0.16, 0.12, 0.1), SHIRT),
        p(2, vec3(0.0, 0.1, 0.0), vec3(0.19, 0.16, 0.11), SHIRT),
        p(3, vec3(0.0, 0.12, 0.01), vec3(0.1, 0.12, 0.11), SKIN),
        p(4, vec3(0.0, -0.14, 0.0), arm, SHIRT),
        p(5, vec3(0.0, -0.14, 0.0), arm * 0.9, SKIN),
        p(6, vec3(0.0, -0.14, 0.0), arm, SHIRT),
        p(7, vec3(0.0, -0.14, 0.0), arm * 0.9, SKIN),
        p(8, vec3(0.0, -0.205, 0.0), leg, TROUSERS),
        p(9, vec3(0.0, -0.205, 0.0), leg * 0.88, TROUSERS),
        p(10, vec3(0.0, -0.04, 0.05), vec3(0.065, 0.04, 0.12), BOOTS),
        p(11, vec3(0.0, -0.205, 0.0), leg, TROUSERS),
        p(12, vec3(0.0, -0.205, 0.0), leg * 0.88, TROUSERS),
        p(13, vec3(0.0, -0.04, 0.05), vec3(0.065, 0.04, 0.12), BOOTS),
    ]
}

/// Every joint's rest transform in model space (rest rotations are identity).
fn rest_globals(joints: &[Joint]) -> Vec<Mat4> {
    let mut out: Vec<Mat4> = Vec::with_capacity(joints.len());
    for joint in joints {
        let local = Mat4::from_translation(joint.at);
        out.push(joint.parent.map_or(local, |parent| out[parent] * local));
    }
    out
}

/// A rotation channel: (joint, times, quaternions).
type Rotations = (usize, Vec<f32>, Vec<Quat>);

/// The walk: legs and arms swing in opposition, the knees bend on the swing, the hips bob and
/// travel forward (+Z, the character's facing).
fn walk() -> (Vec<Rotations>, Vec<f32>, Vec<Vec3>) {
    let times: Vec<f32> = (0..=4).map(|k| WALK_CYCLE * k as f32 / 4.0).collect();
    let swing = |sign: f32| -> Vec<Quat> { [1.0, 0.0, -1.0, 0.0, 1.0].iter().map(|s| Quat::from_rotation_x(sign * 0.45 * s)).collect() };
    let knee = |phase: usize| -> Vec<Quat> { (0..=4).map(|k| Quat::from_rotation_x(if (k + phase) % 4 == 1 { 0.7 } else { 0.05 })).collect() };
    let rotations = vec![
        (8, times.clone(), swing(-1.0)),
        (11, times.clone(), swing(1.0)),
        (9, times.clone(), knee(0)),
        (12, times.clone(), knee(2)),
        (4, times.clone(), swing(0.7)),
        (6, times.clone(), swing(-0.7)),
    ];
    let hips: Vec<Vec3> = (0..=4).map(|k| vec3(0.0, HIPS_HEIGHT + if k % 2 == 1 { 0.03 } else { 0.0 }, WALK_TRAVEL * k as f32 / 4.0)).collect();
    (rotations, times, hips)
}

/// The idle: the chest breathes and the arms hang a little out.
fn idle() -> Vec<Rotations> {
    let times = vec![0.0, 0.5 * IDLE_CYCLE, IDLE_CYCLE];
    let sway = |angle: f32| vec![Quat::IDENTITY, Quat::from_rotation_x(angle), Quat::IDENTITY];
    let hang = |angle: f32| vec![Quat::from_rotation_z(angle); 3];
    vec![(1, times.clone(), sway(0.04)), (4, times.clone(), hang(0.08)), (6, times.clone(), hang(-0.08))]
}

#[derive(Default)]
struct Writer {
    bin: Vec<u8>,
    views: Vec<String>,
    accessors: Vec<String>,
}

impl Writer {
    fn view(&mut self, bytes: &[u8]) -> usize {
        while !self.bin.len().is_multiple_of(4) {
            self.bin.push(0);
        }
        let offset = self.bin.len();
        self.bin.extend_from_slice(bytes);
        self.views.push(format!(r#"{{"buffer":0,"byteOffset":{offset},"byteLength":{}}}"#, bytes.len()));
        self.views.len() - 1
    }

    fn floats(&mut self, values: &[f32], kind: &str, width: usize, bounds: bool) -> usize {
        let bytes: Vec<u8> = values.iter().flat_map(|v| v.to_le_bytes()).collect();
        let view = self.view(&bytes);
        let count = values.len() / width;
        let bounds = if bounds { minmax(values, width) } else { String::new() };
        self.accessors.push(format!(r#"{{"bufferView":{view},"componentType":{FLOAT},"count":{count},"type":"{kind}"{bounds}}}"#));
        self.accessors.len() - 1
    }

    fn shorts(&mut self, values: &[u16], kind: &str, width: usize) -> usize {
        let bytes: Vec<u8> = values.iter().flat_map(|v| v.to_le_bytes()).collect();
        let view = self.view(&bytes);
        let count = values.len() / width;
        self.accessors.push(format!(r#"{{"bufferView":{view},"componentType":{UNSIGNED_SHORT},"count":{count},"type":"{kind}"}}"#));
        self.accessors.len() - 1
    }
}

fn number(value: f32) -> String {
    format!("{value:?}")
}

fn minmax(values: &[f32], width: usize) -> String {
    let mut min = vec![f32::INFINITY; width];
    let mut max = vec![f32::NEG_INFINITY; width];
    for (index, value) in values.iter().enumerate() {
        min[index % width] = min[index % width].min(*value);
        max[index % width] = max[index % width].max(*value);
    }
    let list = |v: &[f32]| v.iter().map(|x| number(*x)).collect::<Vec<_>>().join(",");
    format!(r#","min":[{}],"max":[{}]"#, list(&min), list(&max))
}

/// One box's 24 vertices (4 a face, flat normals) and 36 indices, in model space.
fn cuboid(center: Vec3, half: Vec3, base: u16) -> (Vec<[f32; 3]>, Vec<[f32; 3]>, Vec<u16>) {
    let faces = [(Vec3::X, Vec3::Y), (Vec3::NEG_X, Vec3::Y), (Vec3::Y, Vec3::Z), (Vec3::NEG_Y, Vec3::Z), (Vec3::Z, Vec3::Y), (Vec3::NEG_Z, Vec3::Y)];
    let (mut positions, mut normals, mut indices) = (Vec::new(), Vec::new(), Vec::new());
    for (face, (normal, up)) in faces.iter().enumerate() {
        let side = up.cross(*normal);
        let corner = |u: f32, v: f32| (center + (*normal + side * u + *up * v) * half).to_array();
        positions.extend([corner(-1.0, -1.0), corner(1.0, -1.0), corner(1.0, 1.0), corner(-1.0, 1.0)]);
        normals.extend([normal.to_array(); 4]);
        let at = base + face as u16 * 4;
        indices.extend([at, at + 1, at + 2, at, at + 2, at + 3]);
    }
    (positions, normals, indices)
}

fn node_json(joint: &Joint, children: &[usize]) -> String {
    let children = if children.is_empty() { String::new() } else { format!(r#","children":[{}]"#, children.iter().map(usize::to_string).collect::<Vec<_>>().join(",")) };
    format!(r#"{{"name":"{}","translation":[{},{},{}]{children}}}"#, joint.name, number(joint.at.x), number(joint.at.y), number(joint.at.z))
}

fn rotation_channel(writer: &mut Writer, (joint, times, values): &Rotations, node_offset: usize, samplers: &mut Vec<String>, channels: &mut Vec<String>) {
    let input = writer.floats(times, "SCALAR", 1, true);
    let flat: Vec<f32> = values.iter().flat_map(|q| q.to_array()).collect();
    let output = writer.floats(&flat, "VEC4", 4, false);
    channels.push(format!(r#"{{"sampler":{},"target":{{"node":{},"path":"rotation"}}}}"#, samplers.len(), joint + node_offset));
    samplers.push(format!(r#"{{"input":{input},"output":{output},"interpolation":"LINEAR"}}"#));
}

/// The walker as GLB bytes: node 0 is the skinned mesh, nodes 1.. the joints in skin order.
fn walker_glb() -> Vec<u8> {
    let joints = joints();
    let globals = rest_globals(&joints);
    let mut writer = Writer::default();
    let mut primitives = Vec::new();
    for material in 0..MATERIALS.len() {
        let (mut positions, mut normals, mut indices, mut skin) = (Vec::new(), Vec::new(), Vec::new(), Vec::new());
        for part in parts().iter().filter(|part| part.material == material) {
            let center = globals[part.joint].transform_point3(part.center);
            let (p, n, i) = cuboid(center, part.half, positions.len() as u16);
            skin.extend(std::iter::repeat_n(part.joint as u16, p.len()));
            positions.extend(p);
            normals.extend(n);
            indices.extend(i);
        }
        let position = writer.floats(&positions.concat(), "VEC3", 3, true);
        let normal = writer.floats(&normals.concat(), "VEC3", 3, false);
        let joint_ids: Vec<u16> = skin.iter().flat_map(|joint| [*joint, 0, 0, 0]).collect();
        let joints_accessor = writer.shorts(&joint_ids, "VEC4", 4);
        let weights: Vec<f32> = skin.iter().flat_map(|_| [1.0, 0.0, 0.0, 0.0]).collect();
        let weights_accessor = writer.floats(&weights, "VEC4", 4, false);
        let index = writer.shorts(&indices, "SCALAR", 1);
        primitives.push(format!(
            r#"{{"attributes":{{"POSITION":{position},"NORMAL":{normal},"JOINTS_0":{joints_accessor},"WEIGHTS_0":{weights_accessor}}},"indices":{index},"material":{material}}}"#
        ));
    }
    let inverse_bind: Vec<f32> = globals.iter().flat_map(|global| global.inverse().to_cols_array()).collect();
    let ibm = writer.floats(&inverse_bind, "MAT4", 16, false);
    let (mut walk_samplers, mut walk_channels) = (Vec::new(), Vec::new());
    let (rotations, hip_times, hips) = walk();
    for channel in &rotations {
        rotation_channel(&mut writer, channel, 1, &mut walk_samplers, &mut walk_channels);
    }
    let input = writer.floats(&hip_times, "SCALAR", 1, true);
    let output = writer.floats(&hips.iter().flat_map(|v| v.to_array()).collect::<Vec<_>>(), "VEC3", 3, false);
    walk_channels.push(format!(r#"{{"sampler":{},"target":{{"node":1,"path":"translation"}}}}"#, walk_samplers.len()));
    walk_samplers.push(format!(r#"{{"input":{input},"output":{output},"interpolation":"LINEAR"}}"#));
    let (mut idle_samplers, mut idle_channels) = (Vec::new(), Vec::new());
    for channel in &idle() {
        rotation_channel(&mut writer, channel, 1, &mut idle_samplers, &mut idle_channels);
    }
    let children = |index: usize| joints.iter().enumerate().filter(|(_, j)| j.parent == Some(index)).map(|(child, _)| child + 1).collect::<Vec<_>>();
    let mut nodes = vec![r#"{"name":"Walker","mesh":0,"skin":0}"#.to_owned()];
    nodes.extend(joints.iter().enumerate().map(|(index, joint)| node_json(joint, &children(index))));
    let materials: Vec<String> = MATERIALS
        .iter()
        .map(|(name, [r, g, b, a])| format!(r#"{{"name":"{name}","pbrMetallicRoughness":{{"baseColorFactor":[{},{},{},{}],"metallicFactor":0.0,"roughnessFactor":0.8}}}}"#, number(*r), number(*g), number(*b), number(*a)))
        .collect();
    let skin_joints = (1..=joints.len()).map(|n| n.to_string()).collect::<Vec<_>>().join(",");
    let animations = format!(
        r#"[{{"name":"Idle","channels":[{}],"samplers":[{}]}},{{"name":"Walk","channels":[{}],"samplers":[{}]}}]"#,
        idle_channels.join(","),
        idle_samplers.join(","),
        walk_channels.join(","),
        walk_samplers.join(",")
    );
    let json = format!(
        r#"{{"asset":{{"version":"2.0","generator":"genex slice walker_glb.rs"}},"buffers":[{{"byteLength":{}}}],"bufferViews":[{}],"accessors":[{}],"materials":[{}],"meshes":[{{"name":"Walker","primitives":[{}]}}],"skins":[{{"joints":[{skin_joints}],"inverseBindMatrices":{ibm},"skeleton":1}}],"nodes":[{}],"scenes":[{{"nodes":[0,1]}}],"scene":0,"animations":{animations}}}"#,
        writer.bin.len(),
        writer.views.join(","),
        writer.accessors.join(","),
        materials.join(","),
        primitives.join(","),
        nodes.join(","),
    );
    glb(&json, &writer.bin)
}

/// GLB container bytes around a JSON chunk and a BIN chunk.
fn glb(json: &str, bin: &[u8]) -> Vec<u8> {
    let mut json = json.as_bytes().to_vec();
    while !json.len().is_multiple_of(4) {
        json.push(b' ');
    }
    let mut bin = bin.to_vec();
    while !bin.len().is_multiple_of(4) {
        bin.push(0);
    }
    let total = 12 + 8 + json.len() + 8 + bin.len();
    let mut out = Vec::with_capacity(total);
    out.extend(GLB_MAGIC.to_le_bytes());
    out.extend(2u32.to_le_bytes());
    out.extend((total as u32).to_le_bytes());
    out.extend((json.len() as u32).to_le_bytes());
    out.extend(CHUNK_JSON.to_le_bytes());
    out.extend(&json);
    out.extend((bin.len() as u32).to_le_bytes());
    out.extend(CHUNK_BIN.to_le_bytes());
    out.extend(&bin);
    out
}

fn asset_path() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("assets").join("walker.glb")
}

#[test]
fn the_committed_walker_equals_the_generator_and_the_facade_animates_it() {
    let bytes = walker_glb();
    if std::env::var("GENEX_UPDATE_ASSETS").is_ok_and(|v| v == "1") {
        std::fs::create_dir_all(asset_path().parent().expect("assets folder")).expect("assets folder");
        std::fs::write(asset_path(), &bytes).expect("walker.glb written");
    }
    let committed = std::fs::read(asset_path()).expect("assets/walker.glb: regenerate with GENEX_UPDATE_ASSETS=1");
    assert!(committed == bytes, "assets/walker.glb differs from the generator: regenerate with GENEX_UPDATE_ASSETS=1");

    #[derive(Default)]
    struct Probe {
        clips: Vec<String>,
        moved: f32,
    }
    static TABLE: std::sync::LazyLock<AssetTable> =
        std::sync::LazyLock::new(|| Box::leak(vec![("walker.glb", &*Box::leak(walker_glb().into_boxed_slice()))].into_boxed_slice()));
    let mut game = Game::new(Probe::default());
    game.on_reset(|sim, _, _, gfx| {
        let walker = gfx.character("walker.glb").expect("the walker loads");
        sim.world.clips = walker.clip_names().map(str::to_owned).collect();
        let moving = walker.with_root_motion(&genex::animation::MotionSettings::DEFAULT).expect("root motion");
        let walk = moving.clip("Walk").expect("a walk");
        let mut g = moving.graph();
        let base = g.layer("base");
        g.state(base, "walk", genex::animation::Motion::clip(walk));
        let mut animator = moving.animator(&g.build().expect("graph")).expect("animator");
        for _ in 0..48 {
            sim.world.moved += animator.update(1.0 / 60.0).root_motion.translation.z;
        }
    });
    let runtime = Runtime::with_assets(game, Box::new(*TABLE)).expect("installs");
    let world = &runtime.sim().world;
    assert_eq!(world.clips, ["Idle", "Walk"]);
    assert!((world.moved - WALK_TRAVEL).abs() < 0.02, "one 0.8 s cycle travels {WALK_TRAVEL} m forward (moved {})", world.moved);
}
